      "d": "The Dark Tower, Sauron's stronghold and seat of power, rising from the Plateau of Gorgoroth east of Mount Doom beneath a spur of the Ered Lithui. Built with the power of the One Ring, its foundations cannot be destroyed while the Ring endures. It is a vast fortress of iron and adamant, courts, dungeons and pinnacles; from the Window of the Eye near its summit Sauron keeps watch. A road runs west over an iron bridge toward Orodruin.",
