      "k": 1,
      "d": "The volcano of Mordor, standing alone on the Plateau of Gorgoroth west of Barad-dûr. Its broken base rises some three thousand feet above the plain and its cone half as high again. Sauron forged the One Ring in its fires, and only there can the Ring be unmade. Sauron's Road climbs its eastern face to the Sammath Naur. It burst into flame again at Sauron's return and is stilled only with the Ring's destruction.",
