      "d": "The Chambers of Fire: a long tunnel and high-roofed cavern cut into the cone of Mount Doom, entered by a dark door on its eastern face at the end of Sauron's Road. A short way within, the floor is split by the Cracks of Doom, a chasm glowing with the mountain's fire. Here Sauron forged the One Ring c. S.A. 1600, and here on 25 March T.A. 3019 the Ring was unmade.",
