      "d": "The great fissure cutting across the floor and walls of the Sammath Naur, a short way inside the door: a deep chasm filled with fire, the very heart of Orodruin where the One Ring was forged and where alone it could be destroyed. Isildur refused to cast the Ring into it in S.A. 3441; on 25 March T.A. 3019 Gollum fell into it with the Ring, and the Ring was unmade.",
