      "x": 1699,
      "y": 1594,
      "k": 2,
      "d": "The site of the ending of the Quest of the Ring, in the Sammath Naur on 25 March T.A. 3019. Frodo, at the Cracks of Doom, claimed the Ring for his own; Gollum seized him, bit the Ring from his finger and, dancing on the brink, fell with it into the fire. The Ring was unmade, Barad-dûr and the Black Gate fell, Sauron passed into the shadow, and Mount Doom erupted. The Eagles bore the hobbits from the ruin.",
