      "k": 1,
      "d": "The high, barren plateau of north-western Mordor, enclosed by the Ered Lithui and the Ephel Dúath, on which stand Mount Doom and Barad-dûr. A land of ash, cinder and pitted craters, riddled with orc-camps, arms-deeps and slave-pits, it is crossed by Sauron's roads running from the Morannon, the Isenmouthe and the Morgul Pass to the Dark Tower. Frodo and Sam crossed it to Orodruin in March T.A. 3019.",
