      "r": "Mordor",
      "x": 1830,
      "y": 1795,
      "k": 2,
      "d": "The southern and eastern lowlands of Mordor about the Sea of Núrnen, far from the fumes of Mount Doom. Unlike the ash-deserts of the north, Nurn is fertile: its great fields are tilled by slaves from Sauron's conquered peoples to feed the armies of Mordor. Its rivers flow down from the Ephel Dúath and from a spur of the Ered Lithui. After the War of the Ring King Elessar frees the slaves and gives them Nurn as their own.",
