      "x": 1618,
      "y": 1740,
      "k": 1,
      "d": "The Mountains of Shadow, the great western and southern fence of Mordor. From the Morannon they run south along the border of Ithilien, then bend east to enclose Nurn. Their outer wall is cleft by the Morgul Vale and the high pass of Cirith Ungol; behind their northern stretch runs the lesser ridge of the Morgai. The Harnen rises on their southern slopes. Orc-holds such as Durthang and the Tower of Cirith Ungol guard them.",
