      "x": 1650,
      "y": 1525,
      "k": 2,
      "d": "The Black Gate of Mordor: a rampart of stone with a single great gate of iron, built by Sauron across the mouth of Cirith Gorgor, the Haunted Pass, where the Ered Lithui and the Ephel Dúath meet. It is flanked by the Towers of the Teeth and faces the battle-plain of Dagorlad. Frodo turned aside from it in March T.A. 3019; on 25 March the Host of the West fought its last battle before it, and it fell in ruin.",
