      "x": 1648,
      "y": 1522,
      "k": 2,
      "d": "The two towers, Narchost and Carchost, standing on the hills either side of the Morannon. The Men of Gondor built them early in the Third Age to keep watch on Mordor after Sauron's fall, but the watch failed after the Great Plague and Sauron's servants repaired and garrisoned them. From their windows sleepless eyes watch the Desolation before the Gate. They crash down in the earthquake of 25 March T.A. 3019.",
