      "k": 2,
      "d": "A deep, wide valley just inside the Black Gate, enclosed by arms of the Ered Lithui and the Ephel Dúath. Through it the road runs from Cirith Gorgor south-east to the Isenmouthe and so to Gorgoroth. Udûn is a vast armed camp of Mordor, ringed with tunnels, arms-deeps and orc-holds such as Durthang on the heights above; its Sindarin name means 'hell'. Sauron's armies mustered here before the Battle of the Morannon.",
