      "d": "The 'Iron Jaws': the narrow gap between arms of the Ered Lithui and the Ephel Dúath where the valley of Udûn opens onto Gorgoroth. It is barred by an earthen wall and a great ditch spanned by a single bridge, closed by a fence of pointed iron posts and watched by forts on the rocky spurs. Frodo and Sam were swept toward it among orc-troops on 18 March T.A. 3019, escaping in the dark at the road-meeting.",
      "ev": [
        {
          "y": 3019,
          "a": "TA",
          "yr": 3019,
          "t": "18 March: Frodo and Sam, in sight of the Isenmouthe, are overtaken by Orcs on the road from Durthang."
        },
        {
          "y": 3019,
          "a": "TA",
          "yr": 3019,
          "t": "19 March: the hobbits escape in the confusion at the road-meeting and take the road toward Barad-dûr."
        }
      ],
      "f": null,
      "to": null,
      "pp": [
        "Orcs"
      ],
      "c": "LotR",
      "s": "tg:Isenmouthe",
      "ap": false,
      "fi": false
