      "d": "The 'Pass of the Spider', a high secret pass over the Ephel Dúath from the Morgul Vale into Mordor, north of the Morgul Pass. It is climbed by the Straight Stair and the Winding Stair, then a tunnel through Torech Ungol, the lair of Shelob, to the Cleft at the summit beneath the Tower of Cirith Ungol. Frodo and Sam, led by Gollum, crossed it on 12–13 March T.A. 3019.",
