      "k": 4,
      "d": "Two great three-bodied figures with vulture faces, seated on thrones either side of the arched gate of the Tower of Cirith Ungol. Filled with an evil vigilance, their unseen will bars the gate against any who would pass. Sam broke through it with the Phial of Galadriel on 14 March T.A. 3019; as the hobbits fled the next day the keystone of the arch fell and the Watchers wailed, summoning a Nazgûl.",
