      "d": "A gate of brazen doors closing the Under-way, the tunnel that leads from Shelob's Lair beneath the pass up into the lowest floor of the Tower of Cirith Ungol. Through it the Orcs carried the stung and bound Frodo on 13 March T.A. 3019; Sam, following, found it locked and had to turn back through Torech Ungol and climb to the Tower by the outer gate.",
