      "d": "Shelob's Lair: a stinking tunnel and warren of caverns beneath the summit of the pass of Cirith Ungol, where Shelob the Great, last child of Ungoliant, has dwelt since before Sauron came to Mordor. The Orcs of the Tower use its side-passages at need. On 12–13 March T.A. 3019 Gollum led Frodo and Sam into it; Frodo was stung and bound, and Sam wounded Shelob with Sting and the Phial of Galadriel.",
