      "k": 1,
      "d": "The Dead City: once Minas Ithil, Tower of the Rising Moon, built by Isildur as Gondor's eastern fortress in a valley of the Ephel Dúath facing Minas Anor. Taken by the Nazgûl in T.A. 2002, it became Minas Morgul, the Tower of Sorcery, seat of the Witch-king. Its walls glow with a corpse-pale light, its gate gapes like a mouth, and a bridge of hideous statues crosses the Morgulduin before it. Its host marched on Minas Tirith in T.A. 3019.",
