      "k": 3,
      "d": "Site of the two captures of Minas Ithil. In S.A. 3429 Sauron seized the city and burned the White Tree, driving Isildur to seek Elendil; it was recovered after the Last Alliance. In T.A. 2000 the Nazgûl, leading masterless Men out of Mordor, besieged it in the reign of Eärnil II, and in 2002 they took it with its palantír. Thereafter it was Minas Morgul, and Gondor's kings ended with Eärnur in 2050.",
