      "k": 2,
      "d": "The valley of the Morgulduin in the western Ephel Dúath, opening westward into Ithilien; at its mouth stands Minas Morgul. Once fair, it is now a place of dread: meads of pale, luminous, evil-smelling flowers line the steaming river, and its fumes daze the mind. The Morgul-road climbs the vale to the Morgul Pass. On 19 March T.A. 3019 the Host of the West halted here, burned the meads and broke the bridge.",
