      "k": 3,
      "d": "The main pass over the Ephel Dúath at the head of the Morgul Vale: a great ravine through which the Morgul-road climbs from Minas Morgul into Mordor and descends toward the plain of Gorgoroth. It is the road of the Nazgûl and of the Morgul-host, and the orc-road from the Tower of Cirith Ungol comes down to join it. In March T.A. 3019 the Host of the West guarded the Cross-roads against enemies coming over it.",
