      "d": "Great mounds of crushed rock and fire-blasted, poison-stained earth, heaped up by the Orcs over long years before the Black Gate in the Desolation of the Morannon. On 25 March T.A. 3019 Aragorn drew up the Host of the West on two of these hills, where it was surrounded by the armies of Sauron and held out until the Ring was destroyed and the enemy fled.",
