      "x": 1636,
      "y": 1502,
      "k": 3,
      "d": "The dead land immediately before the Black Gate, south of the Dagorlad: a waste of ash-choked pools, slag-mounds and cones of poisoned earth, defiled by the labour of Sauron's slaves and lifeless for miles about. Frodo and Sam looked on the Morannon from its edge on 5 March T.A. 3019, and the Host of the West camped in it on 24 March before its last battle upon the Slag-hills.",
