      "d": "The last battle of the War of the Ring, fought on 25 March T.A. 3019 before the Black Gate. Aragorn led some six thousand men of Gondor and Rohan to the Slag-hills to draw Sauron's Eye from Frodo; after the parley with the Mouth of Sauron the Gate opened and the host was surrounded by Orcs, Trolls, Easterlings and Haradrim. As the Eagles came the Ring was destroyed, Sauron's power failed, and his armies fled or perished.",
