      "y": 1592,
      "k": 3,
      "d": "The way of the Ring-bearer, 15–25 March T.A. 3019. Escaping the Tower of Cirith Ungol, Frodo and Sam went north along the trough between the Morgai and the Ephel Dúath, climbed to the orc-road from Durthang to the Isenmouthe, were swept along it in an orc-troop and escaped at the road-meeting, then followed the Barad-dûr road east across Gorgoroth. On 22 March they turned south over the plain, cast away their gear, and reached the Sammath Naur on 25 March.",
