      "t": "region",
      "r": "Harad",
      "x": 1650,
      "y": 2180,
      "k": 1,
      "d": "The vast hot lands south of Gondor and Mordor beyond the river Harnen, divided into Near Harad and Far Harad; their bounds to the east and south are unknown in the North. The Haradrim or Southrons are many warring tribes and kingdoms, dark-skinned and fierce, who ride to war with mûmakil. Long dominated by Umbar and by Sauron, they fight Gondor at the Poros, the Pelennor and the Morannon. Hobbits call it the Sunlands.",
