      "x": 1650,
      "y": 2060,
      "k": 2,
      "d": "The northern part of Harad, lying south of the Harnen and of Gondor's lost province of Harondor, between the Bay of Belfalas and Umbar in the west and Khand in the east; the Harad Road runs into it from the north. Its Haradrim are brown-skinned with black hair and dark eyes, and camels roam its dry lands. Its kings warred with Gondor, allied with the Wainriders and Khand in T.A. 1944, and sent men and mûmakil to Sauron's wars.",
