      "d": "The distant, little-known south of Harad, far beyond Near Harad: a land of great heat, dark forests, apes, and the mûmakil or oliphaunts that the Southrons train for war. Its peoples are black-skinned, described by the men of Gondor at the Pelennor as like half-trolls with white eyes and red tongues. Warriors of Far Harad fought for Sauron at the Battle of the Pelennor Fields on 15 March T.A. 3019.",
