      "k": 2,
      "d": "'The South-folk's land', the name written across the southern lands on the maps of Gondor, also rendered Sutherland. It is the country of the Haradrim south of the Harnen and of Mordor's southern mountains, embracing both Near Harad and Far Harad. Beyond the reach of Gondor's later kings, its many tribes are ruled by their own lords, and at the end of the Third Age most are subject to Sauron.",
