      "d": "'South-water', the great river that bounds Harad on the north. It rises on the southern slopes of the Ephel Dúath and flows some five hundred miles south-west and then west, through a wide delta into the Bay of Belfalas midway between the Mouths of Anduin and Umbar. Since the Kin-strife it marks the southern border of Harondor, the debatable land between Gondor and the Corsairs. The Harad Road fords it above its westward bend.",
