      "d": "The campaign of T.A. 1050 in which Ciryaher of Gondor, having bided his time after his father Ciryandil fell at Umbar, came down from the north by land and sea, crossed the river Harnen and utterly defeated the Men of Harad. Their kings acknowledged Gondor's overlordship and their sons were sent as hostages to Osgiliath; Ciryaher took the name Hyarmendacil, 'South-victor', and Gondor reached the height of its power.",
