      "d": "The realm of the Corsairs on the coast south of Gondor: a great cape and the lands about the land-locked firth of the Haven of Umbar. Númenórean since the Second Age and a home of the King's Men, it was won by Gondor in T.A. 933, lost to Castamir's rebels after the Kin-strife, retaken by Telumehtar and lost again. Its Corsairs, mingled with the Haradrim, harry Gondor's coasts and sail for Sauron in the War of the Ring.",
