      "d": "The great natural harbour of Umbar, a land-locked firth sheltered by a long peninsula, with the City of the Corsairs at its eastern end. First fortified by Númenor in S.A. 2280 and long a stronghold of the King's Men, it became Gondor's chief southern haven under the Ship-kings and later the pirate stronghold of the Corsairs. Here Thorongil burned their fleet in T.A. 2980, and hence sailed the black ships defeated at Pelargir in T.A. 3019.",
