      "d": "The land-locked inlet of the sea enclosed by the cape of Umbar, with a narrow entrance from the Bay of Belfalas, forming the finest natural harbour on the southern coasts. Númenórean ships have used it since the Second Age; the fleets of the Ship-kings of Gondor and later of the Corsairs lie here. Off its mouth Eärnil I perished with many ships in a great storm in T.A. 936.",
