      "d": "The siege by land and sea in which Eärnil I, second of the Ship-kings of Gondor, took the Haven of Umbar from the King's Men of Númenórean descent who had held it since the Downfall, making it a great haven and fortress of Gondor. The lords driven out fled to the Haradrim and stirred them to war, and Eärnil himself was lost in a storm off Umbar three years later.",
