      "r": "Umbar",
      "x": 1445,
      "y": 2114,
      "k": 4,
      "d": "The long investment of Gondor's fortress at Umbar by the Men of Harad, led by the lords who had been driven from it. King Ciryandil fell in battle in Haradwaith in T.A. 1015, but the Haven could not be taken because of Gondor's sea-power. For thirty-five years it was beset, until in 1050 Ciryaher came down by land and sea, crossed the Harnen and crushed the Haradrim, taking the name Hyarmendacil.",
