      "d": "During the Long Winter of T.A. 2758–2759, King Helm Hammerhand held out in the Hornburg and the ravine behind it against Wulf's Dunlendings after Edoras itself had fallen. Helm made terrifying solitary sorties against the besiegers before dying still standing at his post; the ravine has been called Helm's Deep ever since.",
